<script setup lang="ts">
import {onMounted,onUnmounted,ref} from 'vue';
import type {RequestFn} from './media';import {traffic,date} from './lib';
type Row=Record<string,any>;const props=defineProps<{request:RequestFn,initial?:string}>();
const rows=ref<Row[]>([]),selected=ref<Row|null>(null),usage=ref<Row|null>(null),devices=ref<Row[]>([]),clients=ref<Row[]>([]),client=ref('auto'),share=ref<Row|null>(null),check=ref<Row|null>(null),qr=ref(''),busy=ref(false),error=ref(''),notice=ref('');
const query=(id:string,c=client.value)=>'?service='+encodeURIComponent(id)+'&client='+encodeURIComponent(c);
const offset=ref(0),total=ref(0);let generation=0;
function clearQR(){if(qr.value)URL.revokeObjectURL(qr.value);qr.value=''}
async function act(fn:()=>Promise<void>){if(busy.value)return;busy.value=true;error.value='';try{await fn()}catch(e){error.value=e instanceof Error?e.message:String(e)}finally{busy.value=false}}
async function list(){const d=await props.request('me/services?offset='+offset.value);rows.value=Array.isArray(d)?d:d.items;total.value=d.total??rows.value.length}
async function details(row:Row,links=true){const ticket=++generation,q=query(row.id);const [s,d]=await Promise.all([props.request('me/service'+q),props.request('me/devices'+q)]);if(ticket!==generation)return;usage.value=s.service;devices.value=d;if(links){clearQR();share.value=null;check.value=null;const [checked,link]=await Promise.all([props.request('me/subscription/check'+q),props.request('me/subscription/share'+q)]);if(ticket!==generation)return;check.value=checked;share.value=link}}
async function open(row:Row){await act(async()=>{selected.value=row;await details(row)})}
async function copied(row:Row){await act(async()=>{const d=await props.request('me/subscription/share'+query(row.id));try{await navigator.clipboard.writeText(d.url);notice.value='已复制 '+row.plan_name+' · '+row.id.slice(0,8)}catch{selected.value=row;await details(row);notice.value='请选中下面的链接手动复制'}})}
async function showQR(){if(!selected.value)return;await act(async()=>{const response=await fetch('/portal/v1/me/subscription/qr'+query(selected.value!.id),{credentials:'same-origin'});if(!response.ok){const d=await response.json().catch(()=>({}));throw new Error(d.error||'二维码暂不可用')}clearQR();qr.value=URL.createObjectURL(await response.blob())})}
async function download(){if(!selected.value)return;await act(async()=>{const c=client.value==='auto'?'mihomo':client.value;const response=await fetch('/portal/v1/me/subscription/content'+query(selected.value!.id,c),{credentials:'same-origin'});if(!response.ok){const d=await response.json().catch(()=>({}));throw new Error(d.error||'配置下载失败，请先检查订阅状态')}const blob=await response.blob();if(!blob.size)throw new Error('配置为空，请联系管理员');const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=/filename="([^"]+)"/.exec(response.headers.get('Content-Disposition')||'')?.[1]||'starhub-config.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);notice.value='已下载 '+c+' 配置；本地文件不会自动更新，请优先导入订阅链接'})}
let timer:ReturnType<typeof setInterval>;onMounted(()=>{void act(async()=>{await list();const d=await props.request('clients');clients.value=Array.isArray(d)?d:(d.clients||d.items||[]);let first=rows.value.find(r=>r.id===props.initial);if(!first&&props.initial){const d=await props.request('me/service?service='+encodeURIComponent(props.initial));if(!d.service)throw new Error('未找到该订单的订阅');first={...d.service,id:props.initial}}if(!props.initial)first=rows.value[0];if(first){selected.value=first;await details(first)}});timer=setInterval(()=>{if(document.visibilityState==='visible'&&!busy.value)void act(async()=>{await list();if(selected.value)await details(selected.value,check.value?.ready!==true)})},30000)});onUnmounted(()=>{generation++;clearInterval(timer);clearQR()});
</script>
<template><div v-if="error" class="alert error" role="alert">{{error}}</div><div v-if="notice" class="alert" role="status">{{notice}}</div><section class="panel"><div class="section-head"><div><h3>按订单管理订阅</h3><p class="muted">每个新订单独立开通；同一套餐购买多次也分别计量、到期和分享。</p></div><select v-model="client" aria-label="客户端格式" :disabled="busy" @change="selected&&open(selected)"><option value="auto">自动识别 · 通用链接</option><option v-for="c in clients.filter(c=>c.id!=='auto')" :value="c.id" :key="c.id">{{c.name||c.label||c.id}}</option></select></div><div class="service-grid"><article v-for="s in rows" :key="s.id" class="service-card" :class="{selected:selected?.id===s.id}"><h3>{{s.plan_name}}</h3><p>{{traffic(s.quota_bytes,s.quota_unit||'GB')}} / 月</p><small class="mono">订单 {{s.id}}</small><small>{{date(s.paid_at)}} 开通</small><span v-if="s.legacy_combined" class="badge">旧版合并权益 · 原链接保留</span><div class="actions"><button :disabled="busy" @click="open(s)">查看此订阅</button><button :disabled="busy" @click="copied(s)">复制此订阅</button></div></article></div><div class="actions" v-if="total>25"><button :disabled="busy||offset===0" @click="act(async()=>{offset=Math.max(0,offset-25);await list()})">上一页</button><span>{{offset+1}}–{{Math.min(offset+25,total)}} / {{total}}</span><button :disabled="busy||offset+25>=total" @click="act(async()=>{offset+=25;await list()})">下一页</button></div><p v-if="!rows.length" class="empty">尚未开通服务。已付款订单需等待身份和节点同步就绪。</p></section>
<section v-if="selected" class="panel"><div class="section-head"><h3>{{selected.plan_name}} · {{selected.id.slice(0,8)}}</h3><span class="badge">独立服务详情</span></div><div v-if="usage" class="metrics"><article><span>剩余流量</span><strong>{{traffic(usage.remaining_bytes,usage.quota_unit||'GB')}}</strong></article><article><span>已用 / 本期配额</span><strong>{{traffic(usage.used_bytes,usage.quota_unit||'GB')}}</strong><small>{{traffic(usage.quota_bytes,usage.quota_unit||'GB')}}</small></article><article><span>到期时间</span><strong class="date">{{date(usage.expires_at)}}</strong></article></div><p v-if="selected.quota_unit==='GB'" class="form-note">此订单按十进制 GB 分配。Clash 常用 GiB 显示：20 GB ≈ 18.63 GiB，字节额度没有减少。新售套餐可由管理员选择 GiB 以统一客户端显示。</p><div v-if="check" class="alert" :class="{error:!check.ready}">{{check.ready?'订阅已就绪':check.reason||'配置同步中'}}<small v-if="check.excluded_nodes">已排除不兼容节点：{{check.excluded_nodes}}</small></div><div v-if="share" class="share-area"><div><label>仅属于此订单的订阅链接<input :value="share.url" readonly @focus="($event.target as HTMLInputElement).select()"></label><div class="actions"><button class="primary" :disabled="busy" @click="copied(selected)">复制链接</button><button :disabled="busy||!!check&&!check.ready" @click="download">下载{{client==='auto'?' Mihomo':''}}配置</button><button :disabled="busy" @click="showQR">显示二维码</button></div><p class="muted">选择实际客户端格式后导入；sing-box 扫码需选择 sing-box。链接包含凭据，请勿公开。</p></div><img v-if="qr" :src="qr" alt="此订单与客户端的订阅二维码" width="180" height="180"></div></section><section v-if="selected" class="panel"><h3>此订阅的设备与客户端记录</h3><p class="muted">按所选订单的独立身份查询。未提供稳定设备标识时，无法保证物理设备去重。</p><div class="table-wrap"><table><thead><tr><th>客户端</th><th>名称</th><th>最近访问</th></tr></thead><tbody><tr v-for="(d,i) in devices" :key="d.id||i"><td>{{d.client_id||d.client||'未提供'}}</td><td>{{d.name||d.id}}</td><td>{{date(d.last_subscription_at||d.last_seen||d.updated_at)}}</td></tr></tbody></table></div><p v-if="!devices.length" class="empty">暂无客户端回传记录</p></section></template>
<style scoped>.service-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,260px),1fr));gap:16px}.service-card{padding:20px;border:1px solid #dce2ec;border-radius:12px;min-width:0}.service-card.selected{border-color:#377d74;background:#f5faf8}.service-card small{display:block;overflow-wrap:anywhere;margin:6px 0}.service-card h3{overflow-wrap:anywhere}.service-card .actions{margin-top:14px}.metrics{margin-bottom:18px}</style>
